import { isRecord, PublisherError } from './util.js';
export const TAKU_SERVICE_CATALOG_SCHEMA_VERSION = 'taku.service-catalog.v1';
export const DEFAULT_TAKU_SERVICE_CATALOG_URL = 'https://ai-proxy.taku.ai/service/catalog/v1';
const SERVICE_CATALOG_PATH = '/service/catalog/v1';
const TRUSTED_SERVICE_CATALOG_ORIGIN = 'https://ai-proxy.taku.ai';
const MAX_SERVICE_CATALOG_BYTES = 8 * 1024 * 1024;
// Proxy endpoint IDs are stable catalog keys, not URL path fragments. Existing
// production entries include dots and case-sensitive operation names.
const CATALOG_ID_PATTERN = /^[a-z][A-Za-z0-9._-]{0,127}$/;
const SHA256_PATTERN = /^sha256:[a-f0-9]{64}$/;
const HTTP_METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE']);
const SERVICE_STATUSES = new Set(['active', 'deprecated', 'disabled']);
export function resolveTakuServiceCatalogUrl(explicit, env = process.env) {
    const configured = String(explicit ||
        env.TAKU_SERVICE_CATALOG_URL ||
        catalogUrlFromProxyBase(env.TAKU_AI_PROXY_BASE_URL) ||
        catalogUrlFromProxyBase(env.TAKU_SERVICE_API_BASE_URL) ||
        DEFAULT_TAKU_SERVICE_CATALOG_URL).trim();
    let url;
    try {
        url = new URL(configured);
    }
    catch {
        throw new PublisherError('Taku service catalog URL is invalid.', 'service_catalog_url_invalid');
    }
    if (url.username || url.password || url.search || url.hash) {
        throw new PublisherError('Taku service catalog URL cannot contain credentials, query parameters, or fragments.', 'service_catalog_url_invalid');
    }
    if (url.pathname === '/' || url.pathname === '') {
        url.pathname = SERVICE_CATALOG_PATH;
    }
    url.pathname = url.pathname.replace(/\/+$/, '');
    if (url.pathname !== SERVICE_CATALOG_PATH) {
        throw new PublisherError(`Taku service catalog URL path must be ${SERVICE_CATALOG_PATH}.`, 'service_catalog_url_invalid');
    }
    if (!trustedCatalogOrigin(url)) {
        throw new PublisherError('Taku service catalog URL must use the production Proxy or a loopback development server.', 'service_catalog_url_untrusted');
    }
    return url.toString();
}
export async function fetchTakuServiceCatalog(request) {
    const url = resolveTakuServiceCatalogUrl(request.url, {});
    const timeoutMs = normalizeCatalogTimeout(request.timeoutMs);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let response;
    try {
        response = await (request.fetchImpl || fetch)(url, {
            method: 'GET',
            headers: { Accept: 'application/json' },
            redirect: 'error',
            signal: controller.signal,
        });
    }
    catch (error) {
        throw new PublisherError(controller.signal.aborted
            ? 'Taku service catalog request timed out.'
            : 'Taku service catalog is unavailable.', controller.signal.aborted
            ? 'service_catalog_timeout'
            : 'service_catalog_unavailable', {
            error: error instanceof Error ? error.message : String(error),
        });
    }
    finally {
        clearTimeout(timer);
    }
    if (!response.ok) {
        throw new PublisherError(`Taku service catalog request failed with HTTP ${response.status}.`, 'service_catalog_unavailable', { status: response.status });
    }
    const contentLength = Number(response.headers.get('content-length') || 0);
    if (Number.isFinite(contentLength) && contentLength > MAX_SERVICE_CATALOG_BYTES) {
        throw new PublisherError('Taku service catalog response is too large.', 'service_catalog_too_large');
    }
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (bytes.byteLength > MAX_SERVICE_CATALOG_BYTES) {
        throw new PublisherError('Taku service catalog response is too large.', 'service_catalog_too_large');
    }
    let parsed;
    try {
        parsed = JSON.parse(new TextDecoder().decode(bytes));
    }
    catch {
        throw new PublisherError('Taku service catalog returned invalid JSON.', 'service_catalog_invalid');
    }
    const catalog = parseTakuServiceCatalog(parsed);
    const etag = String(response.headers.get('etag') || '')
        .trim()
        .replace(/^W\//, '');
    if (etag && etag !== `"${catalog.digest}"`) {
        throw new PublisherError('Taku service catalog ETag does not match its digest.', 'service_catalog_digest_mismatch');
    }
    return catalog;
}
export function validateSubAppServiceMappings(requirements, catalog) {
    const services = new Map(catalog.services.map((service) => [service.id, service]));
    let mappedRequirementsChecked = 0;
    const validated = requirements.map((requirement) => {
        if (requirement.mapping.status !== 'mapped') {
            return cloneRequirement(requirement);
        }
        mappedRequirementsChecked += 1;
        const serviceId = requirement.mapping.serviceId || '';
        const service = services.get(serviceId);
        if (!service || service.status !== 'active') {
            return unavailableRequirement(requirement, `Mapped Taku service "${serviceId}" is not active in catalog ${catalog.digest}.`);
        }
        const endpoints = new Map(service.endpoints.map((endpoint) => [endpoint.id, endpoint]));
        const missing = (requirement.mapping.endpointIds || []).filter((endpointId) => endpoints.get(endpointId)?.status !== 'active');
        if (missing.length > 0) {
            return unavailableRequirement(requirement, `Mapped Taku endpoint(s) are not active for "${serviceId}": ${missing.join(', ')}.`);
        }
        return cloneRequirement(requirement);
    });
    return { requirements: validated, mappedRequirementsChecked };
}
export function failClosedServiceMappings(requirements, reason) {
    return requirements.map((requirement) => {
        if (requirement.mapping.status !== 'mapped') {
            return cloneRequirement(requirement);
        }
        return {
            ...cloneRequirement(requirement),
            mapping: {
                status: 'review-required',
                serviceId: requirement.mapping.serviceId,
                endpointIds: [...(requirement.mapping.endpointIds || [])],
                reason,
            },
        };
    });
}
function parseTakuServiceCatalog(value) {
    const root = record(value, 'service catalog');
    if (root.schema_version !== TAKU_SERVICE_CATALOG_SCHEMA_VERSION) {
        throw invalidCatalog('Unsupported Taku service catalog schema version.');
    }
    const digest = text(root.digest, 'service catalog digest');
    if (!SHA256_PATTERN.test(digest)) {
        throw invalidCatalog('Taku service catalog digest is invalid.');
    }
    const authentication = record(root.authentication, 'service catalog authentication');
    if (authentication.required !== true ||
        authentication.scheme !== 'bearer' ||
        authentication.credential !== 'taku_user_jwt') {
        throw invalidCatalog('Taku service catalog authentication contract is invalid.');
    }
    if (!Array.isArray(root.services)) {
        throw invalidCatalog('Taku service catalog services must be an array.');
    }
    const seenServices = new Set();
    let endpointCount = 0;
    const services = root.services.map((rawService) => {
        const service = record(rawService, 'catalog service');
        const id = catalogId(service.id, 'catalog service id');
        if (seenServices.has(id)) {
            throw invalidCatalog(`Duplicate Taku service catalog ID: ${id}.`);
        }
        seenServices.add(id);
        const status = catalogStatus(service.status, `catalog service ${id} status`);
        if (!Array.isArray(service.endpoints)) {
            throw invalidCatalog(`Catalog service ${id} endpoints must be an array.`);
        }
        const seenEndpoints = new Set();
        const endpoints = service.endpoints.map((rawEndpoint) => {
            const endpoint = record(rawEndpoint, `catalog endpoint for ${id}`);
            const endpointId = catalogId(endpoint.id, `catalog endpoint id for ${id}`);
            if (seenEndpoints.has(endpointId)) {
                throw invalidCatalog(`Duplicate endpoint ID for ${id}: ${endpointId}.`);
            }
            seenEndpoints.add(endpointId);
            endpointCount += 1;
            const method = text(endpoint.method, `catalog endpoint ${id}.${endpointId} method`).toUpperCase();
            if (!HTTP_METHODS.has(method)) {
                throw invalidCatalog(`Unsupported method for ${id}.${endpointId}.`);
            }
            const endpointPath = text(endpoint.path, `catalog endpoint ${id}.${endpointId} path`);
            if (!endpointPath.startsWith('/service/')) {
                throw invalidCatalog(`Unsafe path for ${id}.${endpointId}.`);
            }
            const pricing = record(endpoint.pricing, `catalog endpoint ${id}.${endpointId} pricing`);
            const billingMode = text(pricing.billing_mode, `catalog endpoint ${id}.${endpointId} billing mode`);
            if (billingMode !== 'token' && billingMode !== 'invocation') {
                throw invalidCatalog(`Unsupported billing mode for ${id}.${endpointId}.`);
            }
            const price = catalogPrice(pricing.price, `catalog endpoint ${id}.${endpointId} price`);
            if ((billingMode === 'token' &&
                (price.inputUsd === undefined || price.outputUsd === undefined)) ||
                (billingMode === 'invocation' && price.unitUsd === undefined)) {
                throw invalidCatalog(`Incomplete public price for ${id}.${endpointId}.`);
            }
            return {
                id: endpointId,
                method,
                path: endpointPath,
                summary: optionalText(endpoint.summary),
                inputSchema: optionalText(endpoint.input_schema),
                status: catalogStatus(endpoint.status, `catalog endpoint ${id}.${endpointId} status`),
                pricing: {
                    billingMode,
                    price,
                },
            };
        });
        const basePath = text(service.base_path, `catalog service ${id} base path`);
        const docsPath = text(service.docs_path, `catalog service ${id} docs path`);
        if (!basePath.startsWith('/service/') || !docsPath.startsWith('/service/docs/')) {
            throw invalidCatalog(`Unsafe public paths for catalog service ${id}.`);
        }
        return {
            id,
            title: text(service.title, `catalog service ${id} title`),
            description: optionalText(service.description),
            basePath,
            docsPath,
            status,
            endpoints,
        };
    });
    if (root.service_count !== services.length ||
        root.endpoint_count !== endpointCount) {
        throw invalidCatalog('Taku service catalog counts do not match its contents.');
    }
    return {
        schemaVersion: TAKU_SERVICE_CATALOG_SCHEMA_VERSION,
        digest,
        authentication: {
            required: true,
            scheme: 'bearer',
            credential: 'taku_user_jwt',
        },
        services,
    };
}
function catalogPrice(value, label) {
    const price = record(value, label);
    const result = {};
    for (const [source, target] of [
        ['input_usd', 'inputUsd'],
        ['output_usd', 'outputUsd'],
        ['unit_usd', 'unitUsd'],
    ]) {
        if (price[source] === undefined)
            continue;
        const amount = price[source];
        if (typeof amount !== 'number' || !Number.isFinite(amount) || amount < 0) {
            throw invalidCatalog(`${label} ${source} must be a non-negative number.`);
        }
        result[target] = amount;
    }
    return result;
}
function cloneRequirement(requirement) {
    return {
        ...requirement,
        operations: [...requirement.operations],
        dataClasses: [...requirement.dataClasses],
        mapping: {
            ...requirement.mapping,
            ...(requirement.mapping.endpointIds
                ? { endpointIds: [...requirement.mapping.endpointIds] }
                : {}),
        },
    };
}
function unavailableRequirement(requirement, reason) {
    return {
        ...cloneRequirement(requirement),
        mapping: {
            status: 'unavailable',
            serviceId: requirement.mapping.serviceId,
            endpointIds: [...(requirement.mapping.endpointIds || [])],
            reason,
        },
    };
}
function catalogUrlFromProxyBase(value) {
    const raw = String(value || '').trim();
    if (!raw)
        return '';
    try {
        const url = new URL(raw);
        url.pathname = SERVICE_CATALOG_PATH;
        url.search = '';
        url.hash = '';
        return url.toString();
    }
    catch {
        return raw;
    }
}
function trustedCatalogOrigin(url) {
    if (url.origin === TRUSTED_SERVICE_CATALOG_ORIGIN)
        return true;
    return ((url.protocol === 'http:' || url.protocol === 'https:') &&
        ['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname));
}
function normalizeCatalogTimeout(value) {
    if (value === undefined)
        return 15_000;
    if (!Number.isFinite(value) || value < 1_000 || value > 60_000) {
        throw new PublisherError('Taku service catalog timeout must be between 1 and 60 seconds.', 'service_catalog_timeout_invalid');
    }
    return Math.trunc(value);
}
function catalogStatus(value, label) {
    const status = text(value, label);
    if (!SERVICE_STATUSES.has(status)) {
        throw invalidCatalog(`${label} is invalid.`);
    }
    return status;
}
function catalogId(value, label) {
    const id = text(value, label);
    if (!CATALOG_ID_PATTERN.test(id)) {
        throw invalidCatalog(`${label} is invalid.`);
    }
    return id;
}
function record(value, label) {
    if (!isRecord(value))
        throw invalidCatalog(`${label} must be an object.`);
    return value;
}
function text(value, label) {
    const normalized = typeof value === 'string' ? value.trim() : '';
    if (!normalized)
        throw invalidCatalog(`${label} is required.`);
    return normalized;
}
function optionalText(value) {
    return typeof value === 'string' ? value.trim() : '';
}
function invalidCatalog(message) {
    return new PublisherError(message, 'service_catalog_invalid');
}
